beforeExample:
public class MyClass {
    public void printLines(java.lang.StringBuilder sb, java.lang.String text) {
        sb.append('\r').append('\n').append(text);
    }
    public void printOtherLines(java.lang.StringBuffer sb, java.lang.String text) {
        sb.append('\r').append('\n').append(text);
    }
}

afterExample:
public class MyClass {
    public void printLines(java.lang.StringBuilder sb, java.lang.String text) {
        sb.append(java.lang.System.getProperty("line.separator")).append(text);
    }
    public void printOtherLines(java.lang.StringBuffer sb, java.lang.String text) {
        sb.append(java.lang.System.getProperty("line.separator")).append(text);
    }
}

negativeExample:
public class MyClass {
    public void printOtherChars(java.lang.StringBuilder sb) {
        sb.append('\r'); // Does not contain both '\r' and then '\n'
        sb.append('\n'); // Does not contain both '\r' and then '\n'
        sb.append('X').append('Y'); // Different characters
        sb.append("\n"); // String literal, not character literal
    }
}
